package com.openggf.game.soniccd;
import com.openggf.GameLoop;import com.openggf.game.save.*;import com.openggf.game.session.SessionManager;import com.openggf.game.soniccd.level.*;import com.openggf.game.soniccd.objects.*;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.parallel.Isolated;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import static org.junit.jupiter.api.Assertions.*;
import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;
/** Tests FIRST/allJavaUNRUN. Every seeded row below is an explicitly constructed World control,
 * not a natural route or physics/capture hydration. Existing public TT obligations stay unchanged. */
@Isolated class TestCdOriginalTtSpringWorld extends TestCdOriginalR11LoadingWorld {
 @Test void constructedOrdinaryInitVariantsUseOnlyActualSpringRootsAndNativeDimensions()throws Exception{for(int subtype:new int[]{0,2,4,8})try(var f=start()){f.placement.pool().write(spring(f,0,subtype,4));step(f.loop,0);var row=f.placement.pool().state(127);assertEquals(0x0A,row.id());assertEquals(subtype==4?8:subtype==8?20:2,row.routine());assertEquals(subtype==4?0x208FF8:subtype==8?0x209042:0x208FF2,row.longBits(CdObjectState.LongField.MAPPINGS));assertEquals(subtype==2?0x2520:0x520,row.word(TILE));assertEquals(subtype==4?8:subtype==8?24:16,row.unsignedByte(WIDTH));assertEquals(subtype==4?16:subtype==8?12:8,row.unsignedByte(Y_RADIUS));assertEquals((short)(subtype==2?0xF600:0xF000),row.signedWord(SPRING_SPEED));assertTrue(springSounds(f).isEmpty());assertFalse(f.module.originalR11EntryFrame().closed());}}
 @Test void constructedSpringAndMovingSpringStateReplaysFromBothCaptureKinds()throws Exception{for(boolean moving:new boolean[]{false,true})try(var f=start()){f.placement.pool().write(moving?moving(f):spring(f,0,0,4));var registry=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=registry.capture();var course=registry.captureCourse();step(f.loop,0);var expected=image(f.module);for(boolean c:new boolean[]{false,true}){if(c)registry.restoreCourse(course);else registry.restore(full);step(f.loop,0);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(f.module));}assertFalse(f.module.originalR11EntryFrame().closed());}}
 @Test void constructedSideLaunchUsesPreparedPrimaryAndOneNativeSpringSound()throws Exception{try(var f=start()){var frame=f.module.originalR11EntryFrame();for(int n=0;n<256&&frame.environment().controls().controlLocked()!=0;n++)step(f.loop,0);assertEquals(0,frame.environment().controls().controlLocked(),"Actual Title must unlock input before side-push setup");step(f.loop,8);assertTrue(frame.state().motion().xVelocity()>0,"Actual Right input must produce native push velocity");var motion=f.module.originalR11EntryFrame().state().motion();assertEquals(0,motion.flags()&2,"Native side Spring rejects airborne players");var row=spring(f,8,4,0x85).moveWord(X,((motion.centreX16_16()>>>16)+16)&65535).moveWord(Y,motion.centreY16_16()>>>16).moveByte(WIDTH,8).moveByte(Y_RADIUS,16).moveByte(FLAGS,1);f.placement.pool().write(row);step(f.loop,8);assertEquals(10,f.placement.pool().state(127).routine());assertEquals(-0x1000,f.module.originalR11EntryFrame().state().motion().xVelocity());assertEquals(15,f.module.originalR11EntryFrame().state().motion().moveLock());assertEquals(1,springSounds(f).size());}}
 @Test void idleAndForeignThreadCannotPublishThroughTheCachedSpring()throws Exception{try(var f=start()){f.placement.pool().write(spring(f,0,0,4));var before=f.placement.capture();var frame=f.module.originalR11EntryFrame();var actor=frame.captureActor();var shared=frame.captureShared();var body=(CdSpring)field(f.binding,"spring");var p=new CdSolidObject.Player(new com.openggf.game.soniccd.player.CdPlayerTouchResponse.Actor(frame.state().motion(),frame.state().header().tile(),frame.state().header().priority(),frame.state().timers().hurt(),frame.state().rotationDistance()),frame.state().header().slotId(),frame.state().objectLinks().pushObject(),frame.state().objectLinks().standObject());var g=frame.environment().movement().globals();var globals=new CdSolidObject.Globals(frame.environment().globals().invincible(),g.scoreChain(),g.primaryAngle(),g.secondaryAngle());var input=new CdSpring.SolidInputs(p,new CdSolidObject.Gates(frame.environment().globals().debugMode(),frame.environment().movement().gates().miniSonic()),globals);assertThrows(IllegalStateException.class,()->body.run(127,new CdSpring.Globals(0),input));var failure=new AtomicReference<Throwable>();var t=new Thread(()->{try{body.run(127,new CdSpring.Globals(0),input);}catch(Throwable e){failure.set(e);}});t.start();t.join(5000);assertFalse(t.isAlive());assertInstanceOf(IllegalStateException.class,failure.get());assertEquals(before.pool().slots(),f.placement.capture().pool().slots());assertArrayEquals(before.savedFlags().copy(),f.placement.capture().savedFlags().copy());assertEquals(actor,frame.captureActor());assertEquals(shared,frame.captureShared());}}
 @Test void refusedSpringStoreRetainsItsSourceAndOriginalThrowable()throws Exception{springFault(false);}
 @Test void landedSpringStoreRetainsItsNativeHeaderAndOriginalThrowable()throws Exception{springFault(true);}
 @Test void movingInitKeepsDirtyTileAndItsOneRealSpringChild()throws Exception{try(var f=start()){var row=moving(f);f.placement.pool().write(row);step(f.loop,0);var after=f.placement.pool().state(127);assertEquals(0xCAFE,after.word(TILE),"R41A tile helper is literal RTS");assertEquals(0x2090C0,after.longBits(CdObjectState.LongField.MAPPINGS));assertEquals(7,after.unsignedByte(Y_RADIUS));assertEquals(0x180,after.signedWord(X_VELOCITY));var children=f.placement.pool().capture().slots().stream().filter(s->s.id()==0x0A&&s.word(SPRING_PARENT)==(row.identity().nativeAddress24()&65535)).toList();assertEquals(1,children.size());var child=children.getFirst();assertEquals(0xF0,child.unsignedByte(SPRING_PARENT_Y_OFFSET));assertEquals(row.subtype(),child.subtype());assertEquals(row.centreX(),child.centreX());assertEquals((row.centreY()-16)&65535,child.centreY());}}
 @Test void landedMovingHeaderFaultDoesNotInventTileHelperOrChildWork()throws Exception{try(var f=start()){var seed=moving(f);f.placement.pool().write(seed);var body=(CdMovingSpring)field(f.binding,"mechanismMovingSpring");var protocol=field(body,"mechanismProtocol");var observer=(CdOriginalMechanismProtocol.Observer)field(protocol,"observer");var fault=new Fault();set(protocol,"observer",new CdOriginalMechanismProtocol.Observer(){public void before(CdOriginalMechanismProtocol.Call c){observer.before(c);}public void after(CdOriginalMechanismProtocol.Call c){observer.after(c);if(c.site()==CdOriginalMechanismProtocol.Site.STORE)throw fault;}public void failed(CdOriginalMechanismProtocol.Call c,Throwable t){observer.failed(c,t);}});assertSame(fault,assertThrows(Fault.class,()->step(f.loop,0)));var row=f.placement.pool().state(127);assertEquals(2,row.routine());assertEquals(0xCAFE,row.word(TILE));assertEquals(0x2090C0,row.longBits(CdObjectState.LongField.MAPPINGS));assertEquals(0,fault.getSuppressed().length);assertEquals(0,f.placement.pool().capture().slots().stream().filter(s->s.id()==0x0A&&s.word(SPRING_PARENT)==(seed.identity().nativeAddress24()&65535)).count());}}
 private void springFault(boolean landed)throws Exception{try(var f=start()){var frame=f.module.originalR11EntryFrame();var seed=spring(f,0,0,4);f.placement.pool().write(seed);var body=(CdSpring)field(f.binding,"spring");var actual=(CdSpring.NativeObserver)field(body,"observer");var fault=new Fault();set(body,"observer",new CdSpring.NativeObserver(){public void before(CdSpring.OriginalCall c){if(!landed)throw fault;actual.before(c);}public void after(CdSpring.OriginalCall c){actual.after(c);throw fault;}});assertSame(fault,assertThrows(Fault.class,()->step(f.loop,0)));var row=f.placement.pool().state(127);if(landed){assertEquals(2,row.routine());assertEquals(0x208FF2,row.longBits(CdObjectState.LongField.MAPPINGS));assertEquals(0x520,row.word(TILE));}else assertEquals(seed,row);assertEquals(0,fault.getSuppressed().length);assertTrue(frame.closed());}}
 private static CdObjectState spring(Fixture f,int routine,int subtype,int flags){var m=f.module.originalR11EntryFrame().state().motion();return f.placement.pool().state(127).moveByte(ID,0x0A).moveByte(ROUTINE,routine).moveByte(SUBTYPE,subtype).moveByte(SPRITE_FLAGS,flags).moveWord(X,((m.centreX16_16()>>>16)+96)&65535).moveWord(Y,((m.centreY16_16()>>>16)+64)&65535).moveWord(SPRING_ANCHOR_X,m.centreX16_16()>>>16).moveLong(CdObjectState.LongField.MAPPINGS,0x208FF8).moveWord(TILE,0x520).moveWord(SPRING_SPEED,0xF000);}
 private static CdObjectState moving(Fixture f){var m=f.module.originalR11EntryFrame().state().motion();return f.placement.pool().state(127).moveByte(ID,0x0F).moveByte(ROUTINE,0).moveByte(SUBTYPE,2).moveByte(SUBTYPE2,0xE1).moveWord(TILE,0xCAFE).moveWord(X,((m.centreX16_16()>>>16)+96)&65535).moveWord(Y,((m.centreY16_16()>>>16)+64)&65535);}
 private Fixture start()throws Exception{var source=TestCdOriginalBootPrefix.source();var saves=new SaveManager(root);var profile=CdSaveProfile.fromTemplate(source.initialSaveAssets().orElseThrow()).withPatch(new CdIpxProgress.SavePatch(OptionalInt.of(0x200),OptionalInt.of(4),OptionalInt.of(0x90),OptionalInt.of(0),OptionalInt.of(0x35),OptionalInt.of(2),OptionalInt.of(3)));saves.writeSlot("scd",1,profile.encode());var attempt=SonicCdGameModule.prepareSelectedProfile(source,saves,1,SonicCdGameModule.ProfileEntry.LOAD_GAME,0);var m=attempt.module().orElseThrow();var b=boot();try{var loop=b.bootSonicCdSelectedProfile(source,attempt);for(int n=0;n<256&&m.originalR11LoadingPrefix().main().levelStartedByte()!=1;n++)step(loop,0);step(loop,0);var binding=field(field(m,"r11World"),"binding");var placement=(CdObjectPlacementRuntime)field(binding,"placement");assertEquals(0,placement.pool().state(127).id());return new Fixture(b,loop,m,binding,placement);}catch(Exception|Error e){b.close();throw e;}}
 private record Fixture(com.openggf.tools.HeadlessGameBoot boot,GameLoop loop,SonicCdGameModule module,Object binding,CdObjectPlacementRuntime placement)implements AutoCloseable{public void close(){try{SessionManager.clear();}finally{try{com.openggf.game.GameServices.graphics().cleanup();}finally{boot.close();}}}}
 private static Object image(SonicCdGameModule m){var f=m.originalR11EntryFrame();var p=m.originalR11PlacementImage();return List.of(f.captureActor(),f.captureShared(),p.status(),p.pool().slots(),p.savedFlags(),m.originalR11LoadingPrefix(),m.originalR11LoadingImage(),m.originalR11FirstLoad(),m.originalLoadingWaterImage(),m.originalLoadingWaterPalette(),m.originalR11WorldImage(),m.programServicesState(),m.selectedProfileState());}
 @SuppressWarnings("unchecked")private static List<SonicCdGameModule.PastSpringFm> springSounds(Fixture f)throws Exception{return((List<SonicCdGameModule.PastSound>)field(f.binding,"sounds")).stream().filter(SonicCdGameModule.PastSpringFm.class::isInstance).map(SonicCdGameModule.PastSpringFm.class::cast).toList();}
 private static Object field(Object o,String n)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}private static void set(Object o,String n,Object v)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}private static final class Fault extends RuntimeException{}
}
